    if (INTEGER_WORD_DICTIONARY[num] !== undefined) {
        return INTEGER_WORD_DICTIONARY[num];
    } else if (num === "une" || num === "un") {
        return 1;
    } else if (num.match(/quelques?/)) {
        return 3;
    } else if (num.match(/demi-?/)) {
        return 0.5;
    }

    return parseFloat(num);
}

